import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        N = int(input[index])
        k = int(input[index + 1])
        index += 2
        A = list(map(int, input[index:index + N]))
        index += N
        count = 0
        freq = defaultdict(int)
        for j in range(N):
            target = k + A[j]
            for i in range(64):
                if (target >> i) & 1 == 1:
                    if (A[j] >> i) & 1 == 0:
                        count += freq[(1 << i) - 1 ^ A[j]]
                else:
                    if (A[j] >> i) & 1 == 1:
                        count -= freq[(1 << i) - 1 ^ A[j]]
            freq[A[j]] += 1
        results.append(count)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
